<template>
  <div class="mx-auto max-w-7xl space-y-6 p-4 pb-8">
    <div class="flex flex-col gap-3 md:flex-row md:items-center md:justify-between"><div class="flex items-center gap-3"><Button icon="pi pi-arrow-left" text rounded @click="router.visit('/sales/wholesale-quotes')" /><div><h1 class="text-xl font-semibold text-slate-900">Wholesale Quotation</h1><p class="text-sm text-slate-500">{{ quote?.quote_number || 'Loading quotation…' }}</p></div></div><div v-if="quote" class="flex flex-wrap items-center gap-2"><Button v-if="canManage&&quote.status==='draft'" label="Mark as Sent" icon="pi pi-send" @click="changeStatus('sent')" /><Button v-if="canManage&&quote.status==='sent'" label="Decline" severity="danger" outlined @click="changeStatus('declined')" /><Button v-if="canManage&&quote.status==='sent'" label="Accept" icon="pi pi-check" @click="changeStatus('accepted')" /><Button v-if="canManage&&quote.status==='accepted'" label="Create Sales Order" icon="pi pi-shopping-cart" :loading="saving" @click="convert" /><Button v-if="canManage&&quote.status==='converted'&&quote.order_payment_status!=='paid'&&quote.payment_terms==='bank_transfer'" label="Confirm Bank Transfer" icon="pi pi-building-columns" severity="warn" @click="paymentVisible=true" /><Button v-if="canManage&&quote.status==='converted'&&quote.order_payment_status!=='paid'&&quote.payment_terms!=='bank_transfer'" label="Generate Payment Link" icon="pi pi-link" severity="warn" :loading="saving" @click="createPaymentLink" /><Button v-if="quote.status==='converted'" label="Refresh Payment" icon="pi pi-refresh" severity="secondary" outlined @click="refreshPayment" /><Tag :value="label(quote.status)" :severity="severity(quote.status)" /></div></div>
    <div v-if="loading" class="space-y-3"><Skeleton height="8rem" /><Skeleton height="18rem" /></div>
    <template v-else-if="quote">
      <Message v-if="quote.sales_order_id" severity="success" :closable="false">Invoice {{ quote.invoice_number || quote.quote_number }} · Sales order {{ quote.sales_order_id }} · Payment {{ quote.order_payment_status || 'pending' }}. <button class="font-semibold underline" @click="router.visit(`/sales/pos/orders/${quote.sales_order_id}`)">View order</button></Message>
      <div class="grid gap-3 md:grid-cols-4"><div class="summary"><span>Quotation number</span><b>{{ quote.quote_number }}</b></div><div class="summary"><span>Created</span><b>{{ dateTime(quote.created_at) }}</b></div><div class="summary"><span>Valid until</span><b>{{ dateOnly(quote.valid_until) }}</b></div><div class="summary"><span>Quoted total</span><b class="text-orange-600">{{ money(quote.subtotal) }}</b></div></div>
      <div class="grid gap-4 lg:grid-cols-3"><Card class="border shadow-sm lg:col-span-2"><template #title>Customer and terms</template><template #content><div class="grid gap-4 text-sm md:grid-cols-2"><div><p class="meta">Business customer</p><p class="font-semibold">{{ quote.crm_lead?.full_name||'—' }}</p><p class="text-slate-500">{{ quote.crm_lead?.email||quote.crm_lead?.phone||'No contact' }}</p></div><div><p class="meta">Payment terms</p><p class="font-semibold">{{ paymentTermLabel(quote.payment_terms) }}</p><p v-if="['online_payment','credit_card'].includes(quote.payment_terms)" class="mt-1 text-xs text-slate-500">Processed through PayMongo</p></div></div></template></Card><Card class="border shadow-sm"><template #title>Workflow</template><template #content><ol class="space-y-3 text-sm"><li v-for="step in steps" :key="step.key" class="flex items-center gap-2"><span :class="['flex h-7 w-7 items-center justify-center rounded-full text-xs font-bold',step.done?'bg-emerald-500 text-white':'bg-slate-100 text-slate-400']"><i :class="step.done?'pi pi-check':'pi pi-circle'" /></span><span :class="step.done?'font-medium text-slate-800':'text-slate-400'">{{ step.label }}</span></li></ol></template></Card></div>
      <Card class="border shadow-sm"><template #title>Quoted items</template><template #content><div class="overflow-x-auto"><table class="w-full min-w-[700px] text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-500"><tr><th class="p-3 text-left">#</th><th class="p-3 text-left">Product</th><th class="p-3 text-center">Quantity</th><th class="p-3 text-right">Unit price</th><th class="p-3 text-right">Line total</th></tr></thead><tbody class="divide-y"><tr v-for="(item,i) in quote.items||[]" :key="i"><td class="p-3 text-slate-400">{{ i+1 }}</td><td class="p-3"><p class="font-medium">{{ item.product_name }}</p><p class="text-xs text-slate-500">{{ item.sku||'No SKU' }}</p></td><td class="p-3 text-center">{{ item.quantity }}</td><td class="p-3 text-right">{{ money(item.unit_price) }}</td><td class="p-3 text-right font-semibold">{{ money(item.line_total) }}</td></tr></tbody><tfoot><tr class="border-t-2"><td colspan="4" class="p-3 text-right font-semibold">Total</td><td class="p-3 text-right text-lg font-bold">{{ money(quote.subtotal) }}</td></tr></tfoot></table></div></template></Card>
      <Card v-if="quote.sales_order_id" class="border shadow-sm"><template #title>Payment request</template><template #content><p class="text-sm text-slate-600">Invoice {{ quote.invoice_number || quote.quote_number }} · {{ money(quote.subtotal) }}</p><p v-if="quote.payment_link && quote.order_payment_status !== 'paid'" class="mt-2 break-all text-xs text-orange-700">{{ quote.payment_link }}</p><Button v-if="quote.payment_link && quote.order_payment_status !== 'paid'" label="Copy payment link" icon="pi pi-copy" size="small" severity="warn" outlined class="mt-3" @click="copyPaymentLink" /><p v-if="quote.order_payment_status !== 'paid'" class="mt-2 text-xs text-amber-700">Do not release this order until payment is confirmed.</p></template></Card><Card v-if="quote.notes" class="border shadow-sm"><template #title>Notes</template><template #content><p class="whitespace-pre-line text-sm text-slate-600">{{ quote.notes }}</p></template></Card>
    </template>
    <Dialog v-model:visible="paymentVisible" modal header="Confirm Bank Transfer" class="w-full max-w-md"><Message severity="warn" :closable="false">Check your bank statement first. Confirm only when the full invoice amount has cleared.</Message><div class="mt-4 space-y-3"><div class="field"><label>Bank transaction reference *</label><InputText v-model.trim="payment.reference" fluid placeholder="Reference from bank statement" /></div><label class="flex items-start gap-2 text-sm text-slate-700"><input v-model="payment.confirmed" type="checkbox" class="mt-1 accent-orange-500" />I verified receipt of {{ money(quote?.subtotal) }} in the store bank account.</label></div><template #footer><Button label="Cancel" text severity="secondary" @click="paymentVisible=false" /><Button label="Confirm Received Payment" severity="warn" :disabled="!payment.reference || !payment.confirmed" :loading="saving" @click="recordPayment" /></template></Dialog>
  </div>
</template>
<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue'; import { router,usePage } from '@inertiajs/vue3'; import { useToast } from 'primevue/usetoast'; import { useAuthStore } from '@/stores/auth'; import salesService from '@/services/sales.service'; import Button from 'primevue/button'; import Card from 'primevue/card'; import Dialog from 'primevue/dialog'; import InputText from 'primevue/inputtext'; import Message from 'primevue/message'; import Select from 'primevue/select'; import Skeleton from 'primevue/skeleton'; import Tag from 'primevue/tag'
const page=usePage(),toast=useToast(),auth=useAuthStore(),id=Number((page.props as any).params?.id||location.pathname.split('/').pop()); const canManage=computed(()=>auth.hasPermission('sales.orders.manage')); const quote=ref<any>(null),loading=ref(true),saving=ref(false),paymentVisible=ref(false),payment=reactive({reference:'',confirmed:false})
const rank:any={draft:0,sent:1,accepted:2,converted:3}; const steps=computed(()=>['Draft','Sent','Accepted','Converted'].map((x,i)=>({key:x.toLowerCase(),label:x,done:quote.value?.status==='declined'?i<=1:i<=(rank[quote.value?.status]??0)}))); const load=async()=>{loading.value=true;try{quote.value=(await salesService.getWholesaleQuote(id)).data}catch(e:any){toast.add({severity:'error',summary:'Unable to load quotation',detail:e.response?.data?.message||'Not found.',life:3000})}finally{loading.value=false}}; const changeStatus=async(status:string)=>{try{await salesService.updateWholesaleQuoteStatus(id,status);await load()}catch(e:any){toast.add({severity:'error',summary:'Update failed',detail:e.response?.data?.message,life:3000})}}; const convert=async()=>{saving.value=true;try{await salesService.convertWholesaleQuote(id);await load()}catch(e:any){toast.add({severity:'error',summary:'Conversion failed',detail:e.response?.data?.message,life:3000})}finally{saving.value=false}}; const refreshPayment=async()=>{if(quote.value?.sales_order_id&&quote.value?.payment_link&&quote.value?.order_payment_status!=='paid'){try{await salesService.syncPosOrderPayment(quote.value.sales_order_id)}catch(e:any){toast.add({severity:'warn',summary:'Payment not confirmed',detail:e.response?.data?.message||'Try again shortly.',life:3000})}}await load()}; const recordPayment=async()=>{if(!payment.reference||!payment.confirmed)return;saving.value=true;try{await salesService.recordWholesalePayment(id,{payment_method:'bank_transfer',payment_reference:payment.reference,confirmed_received:true});paymentVisible.value=false;await load()}catch(e:any){toast.add({severity:'error',summary:'Payment failed',detail:e.response?.data?.message,life:3000})}finally{saving.value=false}}
const money=(v:any)=>new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP'}).format(+v||0),label=(v:string)=>String(v||'').replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase()),severity=(v:string)=>v==='converted'?'success':v==='accepted'?'info':v==='declined'?'danger':v==='sent'?'warn':'secondary',dateOnly=(v:any)=>v?new Intl.DateTimeFormat('en-PH',{dateStyle:'medium'}).format(new Date(v)):'No expiry',dateTime=(v:any)=>v?new Intl.DateTimeFormat('en-PH',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v)):'—'; onMounted(load)
const paymentTermLabel=(v:string)=>({cod:'COD (legacy)',online_payment:'PayMongo payment link',credit_card:'PayMongo payment link',bank_transfer:'Verified bank transfer'} as Record<string,string>)[v]||v||'Not specified'
const createPaymentLink=async()=>{saving.value=true;try{await salesService.createWholesalePaymentLink(id);await load();toast.add({severity:'success',summary:'Payment link ready',detail:'Share the link with the customer.',life:3000})}catch(e:any){toast.add({severity:'error',summary:'Unable to create payment link',detail:e.response?.data?.message||'Please try again.',life:3500})}finally{saving.value=false}}
const copyPaymentLink=async()=>{if(!quote.value?.payment_link)return;await navigator.clipboard.writeText(quote.value.payment_link);toast.add({severity:'success',summary:'Payment link copied',life:2000})}
</script>
<style scoped>.summary{border:1px solid #e2e8f0;border-radius:.75rem;background:white;padding:1rem}.summary span,.meta{display:block;font-size:.7rem;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:#64748b}.summary b{display:block;margin-top:.35rem}.field{display:flex;flex-direction:column;gap:.35rem}.field label{font-size:.875rem;font-weight:600}</style>
